03-Mutability.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.36;
contract A { function foo() external pure virtual returns (uint256) {} }
contract B is A { function foo() external pure override virtual returns (uint256) {} }
contract C is A { function foo() external view override virtual returns (uint256) {} }
contract D is B, C { function foo() external override(B, C) virtual returns (uint256) {} }
contract E is C, B { function foo() external pure override(B, C) virtual returns (uint256) {} }
contract F is C, B { function foo() external payable override(B, C) virtual returns (uint256) {} }

